89: ## 3. PKCS#7 Slice-Based Unpadding (`pkcs7_unpad`)
90: 
91: ### 3.1 Specification & Invariants
92: Per RFC 5652 §6.3:
93: - The input block buffer `buf` must have a non-zero length that is an exact multiple of 16 (`buf.len() % 16 == 0`).
94: - The final byte `pad_len = buf[buf.len() - 1]` specifies the number of padding bytes ($1 \le \text{pad\_len} \le 16$).
95: - All bytes in `buf[buf.len() - pad_len ..]` must strictly equal `pad_len`.
96: - If valid, the unpadded plaintext slice is `&buf[..buf.len() - pad_len]`.
97: 
98: ### 3.2 Signature and Implementation Blueprint
99: ```rust
100: /// Strips PKCS#7 padding from a decrypted block buffer.
101: ///
102: /// # Invariants & Security Checks
103: /// 1. `buf` must not be empty and must be an exact multiple of 16 bytes.
104: /// 2. `pad_byte` is extracted from the last byte of `buf`.
105: /// 3. `pad_byte` must satisfy `1 <= pad_byte <= 16` and `pad_byte <= buf.len()`.
106: /// 4. Every byte in `buf[buf.len() - pad_len ..]` must match `pad_byte`.
107: ///
108: /// Returns a zero-copy subslice `&buf[..buf.len() - pad_len]` containing unpadded plaintext.
109: ///
110: /// # Errors
111: /// Returns [`FlightReaderError::DecryptionError`] if:
112: /// - Buffer is empty or not aligned to a 16-byte boundary.
113: /// - Padding length byte is 0, > 16, or exceeds buffer length.
114: /// - Any byte within the padding suffix does not match `pad_byte`.
115: pub fn pkcs7_unpad(buf: &[u8]) -> Result<&[u8], FlightReaderError> {
116:     if buf.is_empty() {
117:         return Err(FlightReaderError::DecryptionError {
118:             reason: "PKCS7 unpadding failed: empty buffer".to_string(),
119:         });
120:     }
121:     if buf.len() % AES_BLOCK_SIZE != 0 {
122:         return Err(FlightReaderError::DecryptionError {
123:             reason: format!(
124:                 "PKCS7 unpadding failed: buffer length {} is not a multiple of 16",
125:                 buf.len()
126:             ),
127:         });
128:     }
129: 
130:     let pad_byte = *buf.last().expect("non-empty buffer has last byte");
131:     let pad_len = pad_byte as usize;
132: 
133:     if pad_len == 0 || pad_len > AES_BLOCK_SIZE || pad_len > buf.len() {
134:         return Err(FlightReaderError::DecryptionError {
135:             reason: format!("PKCS7 unpadding failed: invalid pad length byte {}", pad_byte),
136:         });
137:     }
138: 
139:     let split_idx = buf.len() - pad_len;
140:     let mut valid = true;
141:     for &b in &buf[split_idx..] {
142:         if b != pad_byte {
143:             valid = false;
144:         }
145:     }
146: 
147:     if !valid {
148:         return Err(FlightReaderError::DecryptionError {
149:             reason: "PKCS7 unpadding failed: corrupted padding bytes".to_string(),
150:         });
151:     }
152: 
153:     Ok(&buf[..split_idx])
154: }
155: ```
