159: ## 4. Continuous IV Engine Architecture (`AesContinuousIvEngine`)
160: 
161: ### 4.1 Data Structures
162: 
163: ```rust
164: /// Active cryptographic state for a single FeaturePoint domain.
165: #[derive(Debug, Clone, PartialEq, Eq)]
166: pub struct FeaturePointState {
167:     /// 256-bit AES key.
168:     pub key: [u8; AES_KEY_SIZE],
169:     /// Current 128-bit initialization vector for the next record on this chain.
170:     pub current_iv: [u8; AES_IV_SIZE],
171:     /// Number of records successfully decrypted on this domain chain.
172:     pub records_decrypted: u64,
173: }
174: 
175: impl FeaturePointState {
176:     /// Constructs a new `FeaturePointState` initialized with key and initial IV.
177:     #[inline]
178:     pub const fn new(key: [u8; AES_KEY_SIZE], initial_iv: [u8; AES_IV_SIZE]) -> Self {
179:         Self {
180:             key,
181:             current_iv: initial_iv,
182:             records_decrypted: 0,
183:         }
184:     }
185: }
186: 
187: /// Multi-tenant AES-256-CBC continuous IV chaining engine for DJI flight records.
188: ///
189: /// Preserves CBC cipher state across non-contiguous records belonging to the same
190: /// FeaturePoint domain. Automatically extracts the final 16 ciphertext bytes of each
191: /// record to initialize the subsequent record, enforcing domain isolation across
192: /// FeaturePoints 1 through 14 while allowing unencrypted bypass for FeaturePoint 8.
193: #[derive(Debug, Clone)]
194: pub struct AesContinuousIvEngine {
195:     /// Default key used when initializing FeaturePoints or fallback.
196:     default_key: Option<[u8; AES_KEY_SIZE]>,
197:     /// Default initial IV.
198:     default_iv: Option<[u8; AES_IV_SIZE]>,
199:     /// Domain-isolated keychain state table indexed by FeaturePoint ID (0..=15).
200:     states: [Option<FeaturePointState>; MAX_FEATURE_POINTS],
201: }
202: ```
203: 
204: ### 4.2 Core Method Signatures & Lifecycles
205: 
206: ```rust
207: impl AesContinuousIvEngine {
208:     /// Creates a new engine pre-configured with a master key and initial IV.
209:     ///
210:     /// Initializes FeaturePoint 1 (Base telemetry) and stores default credentials
211:     /// for automatic initialization of any active FeaturePoint domain.
212:     pub fn new(key: [u8; AES_KEY_SIZE], initial_iv: [u8; AES_IV_SIZE]) -> Self {
213:         let mut states: [Option<FeaturePointState>; MAX_FEATURE_POINTS] = Default::default();
214:         states[1] = Some(FeaturePointState::new(key, initial_iv));
215:         Self {
216:             default_key: Some(key),
217:             default_iv: Some(initial_iv),
218:             states,
219:         }
220:     }
221: 
222:     /// Creates an empty engine requiring explicit `set_key` registration per FeaturePoint.
223:     pub fn empty() -> Self {
224:         Self {
225:             default_key: None,
226:             default_iv: None,
227:             states: Default::default(),
228:         }
229:     }
230: 
231:     /// Sets or resets the key and initial IV for a specific FeaturePoint domain.
232:     pub fn set_key(&mut self, feature_point: u8, key: [u8; AES_KEY_SIZE], initial_iv: [u8; AES_IV_SIZE]) {
233:         let idx = feature_point as usize;
234:         if idx < MAX_FEATURE_POINTS {
235:             self.states[idx] = Some(FeaturePointState::new(key, initial_iv));
236:         }
237:     }
238: 
239:     /// Retrieves the current active IV for a FeaturePoint domain (useful for test introspection).
240:     pub fn get_iv(&self, feature_point: u8) -> Option<[u8; AES_IV_SIZE]> {
241:         let idx = feature_point as usize;
242:         if idx < MAX_FEATURE_POINTS {
243:             self.states[idx].as_ref().map(|s| s.current_iv)
244:         } else {
245:             None
246:         }
247:     }
248: 
249:     /// Returns `true` if credentials exist for the given FeaturePoint.
250:     pub fn has_key(&self, feature_point: u8) -> bool {
251:         let idx = feature_point as usize;
252:         if idx < MAX_FEATURE_POINTS {
253:             self.states[idx].is_some() || self.default_key.is_some()
254:         } else {
255:             false
256:         }
257:     }
258: 
259:     /// Returns the number of records decrypted on a FeaturePoint domain.
260:     pub fn records_decrypted(&self, feature_point: u8) -> u64 {
261:         let idx = feature_point as usize;
262:         if idx < MAX_FEATURE_POINTS {
263:             self.states[idx].as_ref().map_or(0, |s| s.records_decrypted)
264:         } else {
265:             0
266:         }
267:     }
268: }
269: ```
270: 
271: ### 4.3 Detailed Decryption Algorithms
272: 
273: #### 1. Destination-Buffer Decryption: `decrypt_record`
274: Writes plaintext into `out_buf` and returns the number of plaintext bytes written:
275: 
276: ```rust
277: pub fn decrypt_record(
278:     &mut self,
279:     feature_point: u8,
280:     ciphertext: &[u8],
281:     out_buf: &mut [u8],
282: ) -> Result<usize, FlightReaderError> {
283:     // 1. FeaturePoint 8 (PlainText) and 0 (Unencrypted) bypass
284:     if feature_point == 8 || feature_point == 0 {
285:         if out_buf.len() < ciphertext.len() {
286:             return Err(FlightReaderError::BufferOverflow {
287:                 required: ciphertext.len(),
288:                 capacity: out_buf.len(),
289:             });
290:         }
291:         out_buf[..ciphertext.len()].copy_from_slice(ciphertext);
292:         return Ok(ciphertext.len());
293:     }
294: 
295:     // 2. Ciphertext length & block boundary checks
296:     if ciphertext.is_empty() {
297:         return Ok(0);
298:     }
299:     if ciphertext.len() < AES_BLOCK_SIZE {
300:         return Err(FlightReaderError::PayloadTooShort {
301:             minimum: AES_BLOCK_SIZE,
302:             available: ciphertext.len(),
303:         });
304:     }
305:     if ciphertext.len() % AES_BLOCK_SIZE != 0 {
306:         return Err(FlightReaderError::DecryptionError {
307:             reason: format!(
308:                 "Ciphertext length {} is not a multiple of 16-byte AES block size",
309:                 ciphertext.len()
310:             ),
311:         });
312:     }
313:     if out_buf.len() < ciphertext.len() {
314:         return Err(FlightReaderError::BufferOverflow {
315:             required: ciphertext.len(),
316:             capacity: out_buf.len(),
317:         });
318:     }
319: 
320:     // 3. Resolve FeaturePoint keychain state
321:     let idx = feature_point as usize;
322:     if idx >= MAX_FEATURE_POINTS {
323:         return Err(FlightReaderError::MissingKey { feature_point });
324:     }
325: 
326:     // Lazily initialize with default credentials if needed
327:     if self.states[idx].is_none() {
328:         if let (Some(k), Some(iv)) = (self.default_key, self.default_iv) {
329:             self.states[idx] = Some(FeaturePointState::new(k, iv));
330:         } else {
331:             return Err(FlightReaderError::MissingKey { feature_point });
332:         }
333:     }
334: 
335:     let state = self.states[idx].as_mut().expect("state initialized");
336: 
337:     // 4. CRITICAL: Extract next IV from ciphertext BEFORE decryption/unpadding
338:     let offset = ciphertext.len() - AES_BLOCK_SIZE;
339:     let mut next_iv = [0u8; AES_IV_SIZE];
340:     next_iv.copy_from_slice(&ciphertext[offset..offset + AES_BLOCK_SIZE]);
341: 
342:     // 5. Decrypt using current IV and key
343:     let decryptor = Aes256CbcDec::new((&state.key).into(), (&state.current_iv).into());
344:     let plaintext_slice = decryptor
345:         .decrypt_padded_b2b_mut::<Pkcs7>(ciphertext, out_buf)
346:         .map_err(|_| FlightReaderError::DecryptionError {
347:             reason: "PKCS7 unpadding failed: corrupted or invalid padding".to_string(),
348:         })?;
349:     let plaintext_len = plaintext_slice.len();
350: 
351:     // 6. State handoff: update IV and counter on success
352:     state.current_iv = next_iv;
353:     state.records_decrypted += 1;
354: 
355:     Ok(plaintext_len)
356: }
357: ```
358: 
359: #### 2. Subslice Returning Helper: `decrypt_into`
360: ```rust
361: /// Decrypts ciphertext into `out_buf` and returns a borrowed subslice of unpadded plaintext.
362: #[inline]
363: pub fn decrypt_into<'a>(
364:     &mut self,
365:     feature_point: u8,
366:     ciphertext: &[u8],
367:     out_buf: &'a mut [u8],
368: ) -> Result<&'a [u8], FlightReaderError> {
369:     let len = self.decrypt_record(feature_point, ciphertext, out_buf)?;
370:     Ok(&out_buf[..len])
371: }
372: ```
373: 
374: #### 3. In-Place Slice Mutation: `decrypt_slice_in_place`
375: Modifies the buffer in-place, returning the unpadded plaintext slice:
376: 
377: ```rust
378: pub fn decrypt_slice_in_place<'a>(
379:     &mut self,
380:     feature_point: u8,
381:     buffer: &'a mut [u8],
382: ) -> Result<&'a [u8], FlightReaderError> {
383:     // 1. FeaturePoint 8 and 0 bypass
384:     if feature_point == 8 || feature_point == 0 {
385:         return Ok(&*buffer);
386:     }
387: 
388:     // 2. Length & boundary checks
389:     if buffer.is_empty() {
390:         return Ok(&[]);
391:     }
392:     if buffer.len() < AES_BLOCK_SIZE {
393:         return Err(FlightReaderError::PayloadTooShort {
394:             minimum: AES_BLOCK_SIZE,
395:             available: buffer.len(),
396:         });
397:     }
398:     if buffer.len() % AES_BLOCK_SIZE != 0 {
399:         return Err(FlightReaderError::DecryptionError {
400:             reason: format!(
401:                 "Ciphertext buffer length {} is not a multiple of 16-byte AES block size",
402:                 buffer.len()
403:             ),
404:         });
405:     }
406: 
407:     // 3. Resolve FeaturePoint state
408:     let idx = feature_point as usize;
409:     if idx >= MAX_FEATURE_POINTS {
410:         return Err(FlightReaderError::MissingKey { feature_point });
411:     }
412:     if self.states[idx].is_none() {
413:         if let (Some(k), Some(iv)) = (self.default_key, self.default_iv) {
414:             self.states[idx] = Some(FeaturePointState::new(k, iv));
415:         } else {
416:             return Err(FlightReaderError::MissingKey { feature_point });
417:         }
418:     }
419:     let state = self.states[idx].as_mut().expect("state initialized");
420: 
421:     // 4. CRITICAL: Extract next IV BEFORE in-place mutation
422:     let offset = buffer.len() - AES_BLOCK_SIZE;
423:     let mut next_iv = [0u8; AES_IV_SIZE];
424:     next_iv.copy_from_slice(&buffer[offset..offset + AES_BLOCK_SIZE]);
425: 
426:     // 5. Decrypt in-place
427:     let decryptor = Aes256CbcDec::new((&state.key).into(), (&state.current_iv).into());
428:     let plaintext_slice = decryptor
429:         .decrypt_padded_mut::<Pkcs7>(buffer)
430:         .map_err(|_| FlightReaderError::DecryptionError {
431:             reason: "PKCS7 unpadding failed: corrupted or invalid padding".to_string(),
432:         })?;
433:     let pt_len = plaintext_slice.len();
434: 
435:     // 6. Update state
436:     state.current_iv = next_iv;
437:     state.records_decrypted += 1;
438: 
439:     Ok(&buffer[..pt_len])
440: }
441: ```
442: 
443: ### 4.4 Standalone Helpers for Testing & Independent Use
444: ```rust
445: /// Decrypts a single standalone AES-256-CBC block with PKCS#7 padding into a destination buffer.
446: pub fn decrypt_cbc_pkcs7(
447:     key: &[u8; AES_KEY_SIZE],
448:     iv: &[u8; AES_IV_SIZE],
449:     ciphertext: &[u8],
450:     out_buf: &mut [u8],
451: ) -> Result<usize, FlightReaderError> {
452:     if ciphertext.is_empty() || ciphertext.len() % AES_BLOCK_SIZE != 0 {
453:         return Err(FlightReaderError::DecryptionError {
454:             reason: "Ciphertext not 16-byte aligned".to_string(),
455:         });
456:     }
457:     if out_buf.len() < ciphertext.len() {
458:         return Err(FlightReaderError::BufferOverflow {
459:             required: ciphertext.len(),
460:             capacity: out_buf.len(),
461:         });
462:     }
463:     let dec = Aes256CbcDec::new(key.into(), iv.into());
464:     let pt = dec
465:         .decrypt_padded_b2b_mut::<Pkcs7>(ciphertext, out_buf)
466:         .map_err(|_| FlightReaderError::DecryptionError {
467:             reason: "PKCS7 unpadding failed".to_string(),
468:         })?;
469:     Ok(pt.len())
470: }
471: 
472: /// Encrypts plaintext using AES-256-CBC with PKCS#7 padding into a destination buffer.
473: pub fn encrypt_cbc_pkcs7(
474:     key: &[u8; AES_KEY_SIZE],
475:     iv: &[u8; AES_IV_SIZE],
476:     plaintext: &[u8],
477:     out_buf: &mut [u8],
478: ) -> Result<usize, FlightReaderError> {
479:     let enc = Aes256CbcEnc::new(key.into(), iv.into());
480:     let ct = enc
481:         .encrypt_padded_b2b_mut::<Pkcs7>(plaintext, out_buf)
482:         .map_err(|_| FlightReaderError::DecryptionError {
483:             reason: "PKCS7 padding failed: insufficient output buffer".to_string(),
484:         })?;
485:     Ok(ct.len())
486: }
487: ```
