142:     /// Registers the 256-bit AES key and initial 128-bit IV for a specific FeaturePoint.
143:     pub fn set_key(&mut self, feature_point: u8, key: [u8; 32], initial_iv: [u8; 16]) {
144:         if feature_point > 0 && (feature_point as usize) < self.keys.len() {
145:             self.keys[feature_point as usize] = Some(key);
146:             self.ivs[feature_point as usize] = Some(initial_iv);
147:         }
148:     }
