151:     pub fn has_key(&self, feature_point: u8) -> bool {
152:         if feature_point > 0 && (feature_point as usize) < self.keys.len() {
153:             self.keys[feature_point as usize].is_some()
154:         } else {
155:             false
156:         }
157:     }
