160:     pub fn current_iv(&self, feature_point: u8) -> Option<[u8; 16]> {
161:         if feature_point > 0 && (feature_point as usize) < self.ivs.len() {
162:             self.ivs[feature_point as usize]
163:         } else {
164:             None
165:         }
166:     }
