//! AES-256-CBC Continuous IV Chaining Engine for modern DJI flight logs (v13 and v14).
//!
//! Implements multi-tenant domain isolation across 14 FeaturePoints, continuous IV handoff
//! where the trailing 16 bytes of record N's intermediate ciphertext become the initialization
//! vector (IV) for record N+1 on that FeaturePoint, zero-allocation in-place slice mutation,
//! destination-buffer decryption, PKCS#7 slice-based unpadding, and FeaturePoint 8 plaintext bypass.
//!
//! Strictly adheres to `#![deny(unsafe_code)]` with zero `unsafe` blocks.

use cbc::cipher::{
    block_padding::{NoPadding, Pkcs7},
    BlockDecryptMut, BlockEncryptMut, KeyIvInit,
};

use crate::error::{FlightReaderError, Result};

/// Standard AES block size in bytes (128 bits).
pub const BLOCK_SIZE: usize = 16;

/// AES-256 key size in bytes (256 bits).
pub const KEY_SIZE: usize = 32;

/// Standard AES initialization vector size in bytes (128 bits).
pub const IV_SIZE: usize = 16;

/// Maximum number of FeaturePoint domain slots (domains 0 through 15).
pub const MAX_FEATURE_POINTS: usize = 16;

/// Standard AES block size in bytes (alias for [`BLOCK_SIZE`]).
pub const AES_BLOCK_SIZE: usize = BLOCK_SIZE;

/// AES-256 key size in bytes (alias for [`KEY_SIZE`]).
pub const AES_KEY_SIZE: usize = KEY_SIZE;

/// Standard AES initialization vector size in bytes (alias for [`IV_SIZE`]).
pub const AES_IV_SIZE: usize = IV_SIZE;

/// Type alias for 256-bit AES-CBC decryptor.
pub type Aes256CbcDec = cbc::Decryptor<aes::Aes256>;

/// Type alias for 256-bit AES-CBC encryptor (used for testing and synthetic stream generation).
pub type Aes256CbcEnc = cbc::Encryptor<aes::Aes256>;

/// Security tenant cryptographic state for a single FeaturePoint domain.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FeaturePointState {
    /// 256-bit AES key.
    pub key: [u8; KEY_SIZE],
    /// Current 128-bit initialization vector for the next record on this chain.
    pub current_iv: [u8; IV_SIZE],
    /// Number of records successfully decrypted on this domain chain.
    pub records_decrypted: u64,
}

impl FeaturePointState {
    /// Constructs a new `FeaturePointState` initialized with key, initial IV, and zero counter.
    #[inline]
    #[must_use]
    pub const fn new(key: [u8; KEY_SIZE], initial_iv: [u8; IV_SIZE]) -> Self {
        Self {
            key,
            current_iv: initial_iv,
            records_decrypted: 0,
        }
    }
}

/// Multi-tenant AES-256-CBC continuous IV chaining engine for DJI flight records.
///
/// Preserves CBC cipher state across non-contiguous records belonging to the same
/// FeaturePoint domain. Automatically extracts the final 16 ciphertext bytes of each
/// record to initialize the subsequent record, enforcing domain isolation across
/// FeaturePoints 1 through 14 while allowing unencrypted bypass for FeaturePoint 8.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AesContinuousIvEngine {
    states: [Option<FeaturePointState>; MAX_FEATURE_POINTS],
    default_key: Option<[u8; KEY_SIZE]>,
    default_iv: Option<[u8; IV_SIZE]>,
}

/// Backward-compatible type alias for [`AesContinuousIvEngine`].
pub type AesEngine = AesContinuousIvEngine;

impl Default for AesContinuousIvEngine {
    #[inline]
    fn default() -> Self {
        Self::empty()
    }
}

impl AesContinuousIvEngine {
    /// Constructs a new `AesContinuousIvEngine` optionally configured with default credentials.
    ///
    /// If `default_key` and `default_iv` are provided, any unkeyed FeaturePoint accessed
    /// during decryption or encryption will be lazily initialized with these credentials.
    #[must_use]
    pub fn new(default_key: Option<[u8; KEY_SIZE]>, default_iv: Option<[u8; IV_SIZE]>) -> Self {
        let mut states: [Option<FeaturePointState>; MAX_FEATURE_POINTS] = Default::default();
        if let (Some(k), Some(iv)) = (default_key, default_iv) {
            states[1] = Some(FeaturePointState::new(k, iv));
        }
        Self {
            states,
            default_key,
            default_iv,
        }
    }

    /// Constructs an empty `AesContinuousIvEngine` requiring explicit [`Self::set_key`] registration.
    #[inline]
    #[must_use]
    pub fn empty() -> Self {
        Self {
            states: Default::default(),
            default_key: None,
            default_iv: None,
        }
    }

    /// Sets or resets the 256-bit key and 128-bit initial IV for a specific FeaturePoint domain.
    pub fn set_key(&mut self, feature_point: u8, key: [u8; KEY_SIZE], iv: [u8; IV_SIZE]) {
        let idx = feature_point as usize;
        if idx < MAX_FEATURE_POINTS {
            self.states[idx] = Some(FeaturePointState::new(key, iv));
        }
    }

    /// Retrieves the current active IV for a FeaturePoint domain, or the default IV if unkeyed.
    #[must_use]
    pub fn get_iv(&self, feature_point: u8) -> Option<[u8; IV_SIZE]> {
        let idx = feature_point as usize;
        if idx < MAX_FEATURE_POINTS {
            self.states[idx]
                .as_ref()
                .map(|s| s.current_iv)
                .or(self.default_iv)
        } else {
            None
        }
    }

    /// Alias for [`Self::get_iv`].
    #[inline]
    #[must_use]
    pub fn current_iv(&self, feature_point: u8) -> Option<[u8; IV_SIZE]> {
        self.get_iv(feature_point)
    }

    /// Returns the number of records decrypted on a specific FeaturePoint domain chain.
    #[must_use]
    pub fn get_records_decrypted(&self, feature_point: u8) -> u64 {
        let idx = feature_point as usize;
        if idx < MAX_FEATURE_POINTS {
            self.states[idx].as_ref().map_or(0, |s| s.records_decrypted)
        } else {
            0
        }
    }

    /// Alias for [`Self::get_records_decrypted`].
    #[inline]
    #[must_use]
    pub fn records_decrypted(&self, feature_point: u8) -> u64 {
        self.get_records_decrypted(feature_point)
    }

    /// Returns `true` if cryptographic credentials are valid for the given FeaturePoint.
    #[must_use]
    pub fn is_keyed(&self, feature_point: u8) -> bool {
        let idx = feature_point as usize;
        if idx < MAX_FEATURE_POINTS {
            self.states[idx].is_some()
                || (self.default_key.is_some() && self.default_iv.is_some())
        } else {
            false
        }
    }

    /// Alias for [`Self::is_keyed`].
    #[inline]
    #[must_use]
    pub fn has_key(&self, feature_point: u8) -> bool {
        self.is_keyed(feature_point)
    }

    /// Decrypts a record payload belonging to `feature_point` into `out_buf` using continuous IV chaining.
    ///
    /// # Protocol Specification & Execution Steps
    /// 1. If `feature_point == 8 || feature_point == 0`: FeaturePoint 8 plaintext bypass.
    ///    Copies `ciphertext` directly into `out_buf` and returns `ciphertext.len()` without touching keys or IVs.
    /// 2. Ensures the target feature point has an active state (or lazily initializes from default key/iv;
    ///    otherwise returns [`FlightReaderError::MissingKey`]).
    /// 3. Validates that `ciphertext.len() >= 16` and `ciphertext.len() % 16 == 0`.
    /// 4. Validates that `out_buf.len() >= ciphertext.len()`.
    /// 5. Extracts `next_iv`: the last 16 bytes of `ciphertext`.
    /// 6. Decrypts blocks into `out_buf[..ciphertext.len()]` using AES-256-CBC.
    /// 7. Validates and removes PKCS#7 padding on `out_buf[..ciphertext.len()]`.
    /// 8. Upon successful unpadding, advances `state.current_iv = next_iv` and increments `state.records_decrypted`.
    /// 9. Returns unpadded plaintext byte length.
    ///
    /// # Errors
    /// - [`FlightReaderError::BufferOverflow`] if `out_buf` capacity is less than required.
    /// - [`FlightReaderError::MissingKey`] if credentials are not configured for this FeaturePoint.
    /// - [`FlightReaderError::PayloadTooShort`] if `ciphertext.len() < 16`.
    /// - [`FlightReaderError::DecryptionError`] if ciphertext length is not a multiple of 16 or PKCS#7 padding is invalid.
    pub fn decrypt_record(
        &mut self,
        feature_point: u8,
        ciphertext: &[u8],
        out_buf: &mut [u8],
    ) -> Result<usize> {
        // 1. FeaturePoint 8 plaintext bypass and unencrypted auxiliary 0
        if feature_point == 8 || feature_point == 0 {
            if out_buf.len() < ciphertext.len() {
                return Err(FlightReaderError::BufferOverflow {
                    required: ciphertext.len(),
                    capacity: out_buf.len(),
                });
            }
            out_buf[..ciphertext.len()].copy_from_slice(ciphertext);
            return Ok(ciphertext.len());
        }

        // 2. Validate ciphertext length and block alignment
        if ciphertext.len() < BLOCK_SIZE {
            return Err(FlightReaderError::PayloadTooShort {
                minimum: BLOCK_SIZE,
                available: ciphertext.len(),
            });
        }
        if ciphertext.len() % BLOCK_SIZE != 0 {
            return Err(FlightReaderError::DecryptionError {
                reason: format!(
                    "Ciphertext length {} is not a multiple of 16-byte AES block size",
                    ciphertext.len()
                ),
            });
        }
        if out_buf.len() < ciphertext.len() {
            return Err(FlightReaderError::BufferOverflow {
                required: ciphertext.len(),
                capacity: out_buf.len(),
            });
        }

        // 3. Ensure feature point has an active state
        let idx = feature_point as usize;
        if idx >= MAX_FEATURE_POINTS {
            return Err(FlightReaderError::MissingKey { feature_point });
        }
        if self.states[idx].is_none() {
            if let (Some(k), Some(iv)) = (self.default_key, self.default_iv) {
                self.states[idx] = Some(FeaturePointState::new(k, iv));
            } else {
                return Err(FlightReaderError::MissingKey { feature_point });
            }
        }
        let state = self.states[idx].as_mut().expect("state is initialized");

        // 4. Extract next IV from the last 16 bytes of ciphertext BEFORE decryption
        let offset = ciphertext.len() - BLOCK_SIZE;
        let mut next_iv = [0u8; IV_SIZE];
        next_iv.copy_from_slice(&ciphertext[offset..offset + BLOCK_SIZE]);

        // 5. Decrypt blocks into out_buf[..ciphertext.len()]
        let dec = Aes256CbcDec::new((&state.key).into(), (&state.current_iv).into());
        dec.decrypt_padded_b2b_mut::<NoPadding>(ciphertext, &mut out_buf[..ciphertext.len()])
            .map_err(|e| FlightReaderError::DecryptionError {
                reason: format!("AES-256-CBC block decryption failed: {e:?}"),
            })?;

        // 6. Validate PKCS7 padding on out_buf[..ciphertext.len()]
        let unpadded = pkcs7_unpad(&out_buf[..ciphertext.len()])?;
        let plaintext_len = unpadded.len();

        // 7. Advance continuous IV state upon successful unpadding
        state.current_iv = next_iv;
        state.records_decrypted += 1;

        Ok(plaintext_len)
    }

    /// Decrypts a record payload directly inside a mutable slice in-place.
    ///
    /// Extracts `next_iv` before in-place mutation, decrypts CBC blocks in-place,
    /// validates PKCS#7 padding, and advances the continuous IV state.
    ///
    /// # Errors
    /// Returns identical errors to [`Self::decrypt_record`].
    pub fn decrypt_slice_in_place(
        &mut self,
        feature_point: u8,
        buffer: &mut [u8],
    ) -> Result<usize> {
        // 1. FeaturePoint 8 plaintext bypass and unencrypted auxiliary 0
        if feature_point == 8 || feature_point == 0 {
            return Ok(buffer.len());
        }

        // 2. Validate ciphertext length and block alignment
        if buffer.len() < BLOCK_SIZE {
            return Err(FlightReaderError::PayloadTooShort {
                minimum: BLOCK_SIZE,
                available: buffer.len(),
            });
        }
        if buffer.len() % BLOCK_SIZE != 0 {
            return Err(FlightReaderError::DecryptionError {
                reason: format!(
                    "Ciphertext buffer length {} is not a multiple of 16-byte AES block size",
                    buffer.len()
                ),
            });
        }

        // 3. Ensure feature point has an active state
        let idx = feature_point as usize;
        if idx >= MAX_FEATURE_POINTS {
            return Err(FlightReaderError::MissingKey { feature_point });
        }
        if self.states[idx].is_none() {
            if let (Some(k), Some(iv)) = (self.default_key, self.default_iv) {
                self.states[idx] = Some(FeaturePointState::new(k, iv));
            } else {
                return Err(FlightReaderError::MissingKey { feature_point });
            }
        }
        let state = self.states[idx].as_mut().expect("state is initialized");

        // 4. Extract next IV from the last 16 bytes BEFORE in-place decryption
        let offset = buffer.len() - BLOCK_SIZE;
        let mut next_iv = [0u8; IV_SIZE];
        next_iv.copy_from_slice(&buffer[offset..offset + BLOCK_SIZE]);

        // 5. Decrypt in-place
        let dec = Aes256CbcDec::new((&state.key).into(), (&state.current_iv).into());
        dec.decrypt_padded_mut::<NoPadding>(buffer)
            .map_err(|e| FlightReaderError::DecryptionError {
                reason: format!("AES-256-CBC block decryption failed: {e:?}"),
            })?;

        // 6. Validate PKCS7 padding
        let unpadded = pkcs7_unpad(buffer)?;
        let plaintext_len = unpadded.len();

        // 7. Advance continuous IV state
        state.current_iv = next_iv;
        state.records_decrypted += 1;

        Ok(plaintext_len)
    }

    /// Convenience zero-allocation method returning borrowed plaintext subslice from `out_buf`.
    #[inline]
    pub fn decrypt_into<'a>(
        &mut self,
        feature_point: u8,
        ciphertext: &[u8],
        out_buf: &'a mut [u8],
    ) -> Result<&'a [u8]> {
        let len = self.decrypt_record(feature_point, ciphertext, out_buf)?;
        Ok(&out_buf[..len])
    }

    /// Allocating convenience variant returning [`Vec<u8>`].
    pub fn decrypt_record_to_vec(
        &mut self,
        feature_point: u8,
        ciphertext: &[u8],
    ) -> Result<Vec<u8>> {
        if feature_point == 8 || feature_point == 0 {
            return Ok(ciphertext.to_vec());
        }
        let mut out_buf = vec![0u8; ciphertext.len()];
        let len = self.decrypt_record(feature_point, ciphertext, &mut out_buf)?;
        out_buf.truncate(len);
        Ok(out_buf)
    }

    /// Encrypts plaintext using AES-256-CBC with PKCS#7 padding into `out_buf`.
    ///
    /// Helper for testing and synthetic stream generation. Updates `current_iv` to
    /// the last 16 bytes of generated ciphertext.
    ///
    /// # Errors
    /// - [`FlightReaderError::BufferOverflow`] if `out_buf` capacity is insufficient for padded ciphertext.
    /// - [`FlightReaderError::MissingKey`] if credentials are not configured for this FeaturePoint.
    pub fn encrypt_record_pkcs7(
        &mut self,
        feature_point: u8,
        plaintext: &[u8],
        out_buf: &mut [u8],
    ) -> Result<usize> {
        // 1. FeaturePoint 8 plaintext bypass and unencrypted auxiliary 0
        if feature_point == 8 || feature_point == 0 {
            if out_buf.len() < plaintext.len() {
                return Err(FlightReaderError::BufferOverflow {
                    required: plaintext.len(),
                    capacity: out_buf.len(),
                });
            }
            out_buf[..plaintext.len()].copy_from_slice(plaintext);
            return Ok(plaintext.len());
        }

        // 2. Ensure feature point has an active state
        let idx = feature_point as usize;
        if idx >= MAX_FEATURE_POINTS {
            return Err(FlightReaderError::MissingKey { feature_point });
        }
        if self.states[idx].is_none() {
            if let (Some(k), Some(iv)) = (self.default_key, self.default_iv) {
                self.states[idx] = Some(FeaturePointState::new(k, iv));
            } else {
                return Err(FlightReaderError::MissingKey { feature_point });
            }
        }
        let state = self.states[idx].as_mut().expect("state is initialized");

        // 3. PKCS7 padding calculation: always pads to next 16-byte multiple (1 to 16 bytes added)
        let padded_len = (plaintext.len() / BLOCK_SIZE + 1) * BLOCK_SIZE;
        if out_buf.len() < padded_len {
            return Err(FlightReaderError::BufferOverflow {
                required: padded_len,
                capacity: out_buf.len(),
            });
        }

        // 4. Encrypt with PKCS7 padding into out_buf
        let enc = Aes256CbcEnc::new((&state.key).into(), (&state.current_iv).into());
        let ct_slice = enc
            .encrypt_padded_b2b_mut::<Pkcs7>(plaintext, out_buf)
            .map_err(|e| FlightReaderError::DecryptionError {
                reason: format!("PKCS7 encryption failed: {e:?}"),
            })?;
        let ct_len = ct_slice.len();

        // 5. Update state.current_iv to last 16 bytes of ciphertext
        let offset = ct_len - BLOCK_SIZE;
        let mut next_iv = [0u8; IV_SIZE];
        next_iv.copy_from_slice(&out_buf[offset..offset + BLOCK_SIZE]);
        state.current_iv = next_iv;

        Ok(ct_len)
    }
}

/// Strips PKCS#7 padding from a decrypted block buffer in zero allocations.
///
/// # Validation Rules
/// 1. `buf.len()` must be non-zero and a multiple of 16 (`buf.len() % 16 == 0` and `buf.len() >= 16`).
/// 2. The final byte `pad` represents the padding length and must satisfy `1 <= pad <= 16`.
/// 3. All `pad` trailing bytes (`buf[buf.len() - pad..]`) must strictly equal `pad`.
///
/// Returns the unpadded plaintext subslice `&buf[..buf.len() - pad]`.
///
/// # Errors
/// Returns [`FlightReaderError::DecryptionError`] if:
/// - Buffer length is `< 16` or not a multiple of 16.
/// - The padding length byte is 0, > 16, or exceeds buffer length.
/// - Any byte within the padding suffix does not match `pad`.
pub fn pkcs7_unpad(buf: &[u8]) -> Result<&[u8]> {
    if buf.len() < BLOCK_SIZE || buf.len() % BLOCK_SIZE != 0 {
        return Err(FlightReaderError::DecryptionError {
            reason: format!(
                "PKCS7 unpadding failed: buffer length {} is not a non-zero multiple of 16",
                buf.len()
            ),
        });
    }

    let pad_byte = *buf.last().expect("buffer length is non-zero");
    let pad = pad_byte as usize;

    if pad == 0 || pad > BLOCK_SIZE || pad > buf.len() {
        return Err(FlightReaderError::DecryptionError {
            reason: format!("PKCS7 unpadding failed: invalid pad length byte {pad_byte}"),
        });
    }

    let split_idx = buf.len() - pad;
    let mut valid = true;
    for &b in &buf[split_idx..] {
        if b != pad_byte {
            valid = false;
        }
    }

    if !valid {
        return Err(FlightReaderError::DecryptionError {
            reason: "PKCS7 unpadding failed: corrupted padding bytes".to_string(),
        });
    }

    Ok(&buf[..split_idx])
}

/// Decrypts a single standalone AES-256-CBC block with PKCS#7 padding into `out_buf`.
pub fn decrypt_cbc_pkcs7(
    key: &[u8; KEY_SIZE],
    iv: &[u8; IV_SIZE],
    ciphertext: &[u8],
    out_buf: &mut [u8],
) -> Result<usize> {
    if ciphertext.len() < BLOCK_SIZE || ciphertext.len() % BLOCK_SIZE != 0 {
        return Err(FlightReaderError::DecryptionError {
            reason: "Ciphertext not 16-byte aligned".to_string(),
        });
    }
    if out_buf.len() < ciphertext.len() {
        return Err(FlightReaderError::BufferOverflow {
            required: ciphertext.len(),
            capacity: out_buf.len(),
        });
    }
    let dec = Aes256CbcDec::new(key.into(), iv.into());
    dec.decrypt_padded_b2b_mut::<NoPadding>(ciphertext, &mut out_buf[..ciphertext.len()])
        .map_err(|e| FlightReaderError::DecryptionError {
            reason: format!("CBC block decryption failed: {e:?}"),
        })?;
    let unpadded = pkcs7_unpad(&out_buf[..ciphertext.len()])?;
    Ok(unpadded.len())
}

/// Encrypts plaintext using AES-256-CBC with PKCS#7 padding into `out_buf`.
pub fn encrypt_cbc_pkcs7(
    key: &[u8; KEY_SIZE],
    iv: &[u8; IV_SIZE],
    plaintext: &[u8],
    out_buf: &mut [u8],
) -> Result<usize> {
    let padded_len = (plaintext.len() / BLOCK_SIZE + 1) * BLOCK_SIZE;
    if out_buf.len() < padded_len {
        return Err(FlightReaderError::BufferOverflow {
            required: padded_len,
            capacity: out_buf.len(),
        });
    }
    let enc = Aes256CbcEnc::new(key.into(), iv.into());
    let ct = enc
        .encrypt_padded_b2b_mut::<Pkcs7>(plaintext, out_buf)
        .map_err(|e| FlightReaderError::DecryptionError {
            reason: format!("PKCS7 padding failed: {e:?}"),
        })?;
    Ok(ct.len())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_pkcs7_unpad_all_pad_lengths_1_to_16() {
        for pad_len in 1..=16 {
            let mut block = vec![0x42; 32 - pad_len];
            block.extend(std::iter::repeat(pad_len as u8).take(pad_len));
            assert_eq!(block.len(), 32);

            let unpadded = pkcs7_unpad(&block).unwrap();
            assert_eq!(unpadded.len(), 32 - pad_len);
            assert_eq!(unpadded, vec![0x42; 32 - pad_len].as_slice());
        }
    }

    #[test]
    fn test_pkcs7_unpad_corrupted_padding_rejections() {
        // Pad byte 0
        let mut b1 = vec![0x42; 15];
        b1.push(0x00);
        assert!(pkcs7_unpad(&b1).is_err());

        // Pad byte > 16
        let mut b2 = vec![0x42; 15];
        b2.push(17);
        assert!(pkcs7_unpad(&b2).is_err());

        // Corrupted sequence: last is 3, but prefix is [3, 2, 3]
        let mut b3 = vec![0x42; 13];
        b3.extend_from_slice(&[3, 2, 3]);
        assert!(pkcs7_unpad(&b3).is_err());

        // Non-block aligned length (15 bytes)
        let b4 = vec![0x42; 15];
        assert!(pkcs7_unpad(&b4).is_err());

        // Empty buffer
        assert!(pkcs7_unpad(&[]).is_err());
    }

    #[test]
    fn test_aes_standalone_cbc_pkcs7_roundtrip() {
        let key = [0x55u8; 32];
        let iv = [0xAAu8; 16];
        let pt = b"Testing AES-256-CBC with PKCS7 standalone";

        let mut ct_buf = [0u8; 64];
        let ct_len = encrypt_cbc_pkcs7(&key, &iv, pt, &mut ct_buf).unwrap();

        let mut out_pt = [0u8; 64];
        let pt_len = decrypt_cbc_pkcs7(&key, &iv, &ct_buf[..ct_len], &mut out_pt).unwrap();

        assert_eq!(&out_pt[..pt_len], pt);
    }
}

