/// De-scrambles and decrypts payload into `out_buf` using an optional continuous IV engine.
///
/// # Behavior by Version
/// - **v1–v6**: Direct zero-allocation memory copy into `out_buf`.
/// - **v7–v12**: ECMA-182 CRC64 cyclic XOR de-scramble into `out_buf`.
/// - **v13–v14**:
///   - FeaturePoint 8 (`KeyStorage` 56, `FlightRecordRecover` 50, etc.) and FeaturePoint 0 (unencrypted auxiliary):
///     bypasses AES decryption. If XOR scrambled on wire (length % 16 == 1), de-scrambles XOR into `out_buf`;
///     otherwise copies raw bytes.
///   - Encrypted FeaturePoints:
///     * If XOR scrambled on wire (`payload.len() >= 2 && payload.len() % 16 == 1`): de-scrambles XOR into `out_buf`.
///     * Otherwise: copies raw payload into `out_buf`.
///     * If an AES engine is provided, decrypts in-place with continuous IV chaining, validates PKCS#7 padding,
///       and returns unpadded plaintext slice.
///     * If no AES engine is provided (`aes == None`), returns the XOR de-scrambled bytes as raw ciphertext.
pub fn decode_into_with_aes<'b>(
    &self,
    version: u8,
    out_buf: &'b mut [u8],
    mut aes: Option<&mut AesContinuousIvEngine>,
) -> Result<&'b [u8]> {
    let caps = classify_version(version)?;
    match caps.scramble_type {
        ScrambleType::None => {
            if out_buf.len() < self.payload.len() {
                return Err(FlightReaderError::BufferOverflow {
                    required: self.payload.len(),
                    capacity: out_buf.len(),
                });
            }
            out_buf[..self.payload.len()].copy_from_slice(self.payload);
            Ok(&out_buf[..self.payload.len()])
        }
        ScrambleType::Xor => {
            if self.payload.is_empty() {
                return Ok(&[]);
            }
            if self.payload.len() < 2 {
                return Err(FlightReaderError::PayloadTooShort {
                    minimum: 2,
                    available: self.payload.len(),
                });
            }
            let plaintext_len = self.payload.len() - 1;
            if out_buf.len() < plaintext_len {
                return Err(FlightReaderError::BufferOverflow {
                    required: plaintext_len,
                    capacity: out_buf.len(),
                });
            }
            let seed = self.payload[0];
            let key = crate::crypto::derive_key(self.record_type, seed);
            xor::descramble_slice(&self.payload[1..], &mut out_buf[..plaintext_len], key)?;
            Ok(&out_buf[..plaintext_len])
        }
        ScrambleType::Aes => {
            let fp = get_feature_point(version, self.record_type);
            if fp == 8 || fp == 0 {
                // FeaturePoint 8 plaintext bypass or unencrypted auxiliary
                if self.payload.is_empty() {
                    return Ok(&[]);
                }
                if self.payload.len() >= 2 && self.payload.len() % 16 == 1 {
                    let plaintext_len = self.payload.len() - 1;
                    if out_buf.len() < plaintext_len {
                        return Err(FlightReaderError::BufferOverflow {
                            required: plaintext_len,
                            capacity: out_buf.len(),
                        });
                    }
                    let seed = self.payload[0];
                    let key = crate::crypto::derive_key(self.record_type, seed);
                    xor::descramble_slice(&self.payload[1..], &mut out_buf[..plaintext_len], key)?;
                    Ok(&out_buf[..plaintext_len])
                } else {
                    if out_buf.len() < self.payload.len() {
                        return Err(FlightReaderError::BufferOverflow {
                            required: self.payload.len(),
                            capacity: out_buf.len(),
                        });
                    }
                    out_buf[..self.payload.len()].copy_from_slice(self.payload);
                    Ok(&out_buf[..self.payload.len()])
                }
            } else {
                // Encrypted FeaturePoint domain
                if self.payload.is_empty() {
                    return Ok(&[]);
                }
                let (ct_len, is_xord) = if self.payload.len() >= 2 && self.payload.len() % 16 == 1 {
                    (self.payload.len() - 1, true)
                } else {
                    (self.payload.len(), false)
                };

                if out_buf.len() < ct_len {
                    return Err(FlightReaderError::BufferOverflow {
                        required: ct_len,
                        capacity: out_buf.len(),
                    });
                }

                if is_xord {
                    let seed = self.payload[0];
                    let key = crate::crypto::derive_key(self.record_type, seed);
                    xor::descramble_slice(&self.payload[1..], &mut out_buf[..ct_len], key)?;
                } else {
                    out_buf[..ct_len].copy_from_slice(self.payload);
                }

                if let Some(engine) = aes.as_deref_mut() {
                    let pt_len = engine.decrypt_slice_in_place(fp, &mut out_buf[..ct_len])?;
                    Ok(&out_buf[..pt_len])
                } else {
                    // If no AES engine provided, return XOR de-scrambled bytes as raw ciphertext
                    Ok(&out_buf[..ct_len])
                }
            }
        }
    }
}

/// De-scrambles or passes through the record payload into a caller-provided destination slice.
///
/// Preserves backward compatibility by delegating to [`Self::decode_into_with_aes`] with `aes: None`.
#[inline]
pub fn decode_into<'b>(&self, version: u8, out_buf: &'b mut [u8]) -> Result<&'b [u8]> {
    self.decode_into_with_aes(version, out_buf, None)
}

/// Automatically routes and decodes payload according to log format version capabilities with AES support.
pub fn decode_payload_with_aes(
    &self,
    version: u8,
    mut aes: Option<&mut AesContinuousIvEngine>,
) -> Result<RecordPayload<'a>> {
    let caps = classify_version(version)?;
    match caps.scramble_type {
        ScrambleType::None => Ok(RecordPayload::Borrowed(self.payload)),
        ScrambleType::Xor => {
            if self.payload.is_empty() {
                return Ok(RecordPayload::Borrowed(&[]));
            }
            if self.payload.len() < 2 {
                return Err(FlightReaderError::PayloadTooShort {
                    minimum: 2,
                    available: self.payload.len(),
                });
            }
            let descrambled = xor::descramble_record_to_vec(self.payload, self.record_type)?;
            Ok(RecordPayload::Owned(descrambled))
        }
        ScrambleType::Aes => {
            let fp = get_feature_point(version, self.record_type);
            if fp == 8 || fp == 0 {
                if self.payload.is_empty() {
                    return Ok(RecordPayload::Borrowed(&[]));
                }
                if self.payload.len() >= 2 && self.payload.len() % 16 == 1 {
                    let descrambled = xor::descramble_record_to_vec(self.payload, self.record_type)?;
                    Ok(RecordPayload::Owned(descrambled))
                } else {
                    Ok(RecordPayload::Borrowed(self.payload))
                }
            } else {
                if self.payload.is_empty() {
                    return Ok(RecordPayload::Borrowed(&[]));
                }
                let is_xord = self.payload.len() >= 2 && self.payload.len() % 16 == 1;
                if let Some(engine) = aes.as_deref_mut() {
                    let ct = if is_xord {
                        xor::descramble_record_to_vec(self.payload, self.record_type)?
                    } else {
                        self.payload.to_vec()
                    };
                    let decrypted = engine.decrypt_record_to_vec(fp, &ct)?;
                    Ok(RecordPayload::Owned(decrypted))
                } else {
                    if is_xord {
                        let descrambled = xor::descramble_record_to_vec(self.payload, self.record_type)?;
                        Ok(RecordPayload::Owned(descrambled))
                    } else {
                        Ok(RecordPayload::Borrowed(self.payload))
                    }
                }
            }
        }
    }
}

