#[derive(Debug, Clone)]
pub struct RecordEnvelopeIterator<'a> {
    buffer: &'a [u8],
    current_offset: usize,
    end_offset: usize,
    capabilities: VersionCapabilities,
    header_offset: usize,
    resync: bool,
    aes_engine: Option<AesContinuousIvEngine>,
}

impl<'a> RecordEnvelopeIterator<'a> {
    /// Constructs a new `RecordEnvelopeIterator` from a flight log buffer and parsed header.
    ///
    /// # Stream Boundary Resolution
    /// - **v1–v11** (`DetailsLocation::EndOfFile`): Telemetry records reside from `header_length`
    ///   (100 bytes) up to `details_offset`.
    /// - **v12–v14** (`DetailsLocation::HeaderOffset`): Summary details reside between `header_length`
    ///   and `details_offset`, and telemetry records begin at `details_offset` running to EOF (`buffer.len()`).
    ///
    /// # Errors
    /// Returns [`FlightReaderError::CorruptedHeader`] if `details_offset` is negative.
    /// Returns [`FlightReaderError::UnsupportedVersion`] if header version is unhandled.
    pub fn new(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
        let capabilities = header.capabilities()?;
        let header_offset = header.header_length as usize;

        let (current_offset, end_offset) = match capabilities.details_location {
            DetailsLocation::EndOfFile => {
                let end = if header.details_offset >= 0 {
                    (header.details_offset as usize).min(buffer.len())
                } else {
                    return Err(FlightReaderError::CorruptedHeader);
                };
                let start = header_offset.min(end);
                (start, end)
            }
            DetailsLocation::HeaderOffset => {
                let start = if header.details_offset >= 0 {
                    (header.details_offset as usize).min(buffer.len())
                } else {
                    return Err(FlightReaderError::CorruptedHeader);
                };
                (start, buffer.len())
            }
        };

        Ok(Self {
            buffer,
            current_offset,
            end_offset,
            capabilities,
            header_offset,
            resync: true,
            aes_engine: None,
        })
    }

    /// Alias for [`Self::new`] for explicit naming.
    #[inline]
    pub fn from_header(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
        Self::new(buffer, header)
    }

    /// Constructs an iterator over a raw record slice with known version capabilities.
    #[inline]
    pub fn from_slice(slice: &'a [u8], capabilities: VersionCapabilities) -> Self {
        Self {
            buffer: slice,
            current_offset: 0,
            end_offset: slice.len(),
            capabilities,
            header_offset: 0,
            resync: true,
            aes_engine: None,
        }
    }

    /// Configures an AES continuous IV chaining engine for modern DJI log decryption.
    #[inline]
    #[must_use]
    pub fn with_aes_engine(mut self, engine: AesContinuousIvEngine) -> Self {
        self.aes_engine = Some(engine);
        self
    }

    /// Sets or updates the cryptographic credentials for a FeaturePoint domain.
    #[must_use]
    pub fn with_key(mut self, feature_point: u8, key: [u8; 32], iv: [u8; 16]) -> Self {
        let mut engine = self.aes_engine.unwrap_or_else(AesContinuousIvEngine::empty);
        engine.set_key(feature_point, key, iv);
        self.aes_engine = Some(engine);
        self
    }

    /// Sets or updates the active AES engine.
    #[inline]
    pub fn set_aes_engine(&mut self, engine: AesContinuousIvEngine) {
        self.aes_engine = Some(engine);
    }

    /// Returns shared access to the active AES engine, if configured.
    #[inline]
    #[must_use]
    pub fn aes_engine(&self) -> Option<&AesContinuousIvEngine> {
        self.aes_engine.as_ref()
    }

    /// Returns mutable access to the active AES engine, if configured.
    #[inline]
    pub fn aes_engine_mut(&mut self) -> Option<&mut AesContinuousIvEngine> {
        self.aes_engine.as_mut()
    }

    /// Decodes an envelope's payload into `out_buf` using the iterator's version and AES session.
    #[inline]
    pub fn decode_into<'b>(
        &mut self,
        env: &RawRecordEnvelope<'a>,
        out_buf: &'b mut [u8],
    ) -> Result<&'b [u8]> {
        env.decode_into_with_aes(self.capabilities.version, out_buf, self.aes_engine.as_mut())
    }

    /// Decodes an envelope's payload into a [`RecordPayload`] using the iterator's version and AES session.
    #[inline]
    pub fn decode_payload(&mut self, env: &RawRecordEnvelope<'a>) -> Result<RecordPayload<'a>> {
        env.decode_payload_with_aes(self.capabilities.version, self.aes_engine.as_mut())
    }

    /// Configures whether resilient stream resynchronization is enabled.
    ///
    /// In resilient mode (`resync: true`, default), corrupted delimiters or framing errors
    /// advance forward byte-by-byte (`cursor += 1`) to search for the next valid record boundary
    /// without panicking or terminating early.
    #[inline]
    pub fn with_resync(mut self, resync: bool) -> Self {
        self.resync = resync;

