    #[test]
    fn test_aes_standalone_cbc_pkcs7_roundtrip() {
        let key = [0x55u8; 32];
        let iv = [0xAAu8; 16];
        let pt = b"Testing AES-256-CBC with PKCS7 standalone";

        let mut ct_buf = [0u8; 64];
        let ct_len = encrypt_cbc_pkcs7(&key, &iv, pt, &mut ct_buf).unwrap();

        let mut out_pt = [0u8; 64];
        let pt_len = decrypt_cbc_pkcs7(&key, &iv, &ct_buf[..ct_len], &mut out_pt).unwrap();

        assert_eq!(&out_pt[..pt_len], pt);
    }

    #[test]
    fn test_engine_continuous_iv_tracking_and_records_decrypted() {
        let key = [0x11u8; 32];
        let initial_iv = [0x22u8; 16];
        let mut engine = AesContinuousIvEngine::new(None, None);
        assert!(!engine.is_keyed(10));
        assert_eq!(engine.get_records_decrypted(10), 0);
        assert_eq!(engine.get_iv(10), None);

        engine.set_key(10, key, initial_iv);
        assert!(engine.is_keyed(10));
        assert_eq!(engine.get_iv(10), Some(initial_iv));

