//! Comprehensive Integration Test Suite: AES-256-CBC Continuous IV Chaining Engine
//!
//! Validates:
//! 1. Bit-exact reference test vectors from `tests/empirical/test_cryptographic_math.py`.
//! 2. Continuous IV chaining across sequential packets vs naive initial IV corruption.
//! 3. Multi-tenant FeaturePoint domain isolation (interleaving FP 10 and FP 11).
//! 4. FeaturePoint 8 (`KeyStorage` 56, `FlightRecordRecover` 50) plaintext bypass.
//! 5. PKCS#7 padding validation, corrupt suffix rejection, and length alignment errors.
//! 6. Typed [`FlightReaderError::MissingKey`] on unconfigured domains.
//! 7. End-to-end synthetic DJI v13 and v14 log demuxing and decryption with [`RecordEnvelopeIterator`].
//! 8. Zero heap allocations on decryption hot paths.

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::crypto::{
    pkcs7_unpad, Aes256CbcDec, AesContinuousIvEngine, BLOCK_SIZE, IV_SIZE, KEY_SIZE,
};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::{
    get_feature_point, RawRecordEnvelope, RecordEnvelopeIterator, TxtHeader, RECORD_DELIMITER,
};

fn hex_to_bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("valid hex byte"))
        .collect()
}

fn hex_to_32(s: &str) -> [u8; 32] {
    let v = hex_to_bytes(s);
    v.try_into().expect("32 bytes hex")
}

fn hex_to_16(s: &str) -> [u8; 16] {
    let v = hex_to_bytes(s);
    v.try_into().expect("16 bytes hex")
}

/// Helper to create a minimal synthetic 100-byte DJI `.txt` file header.
fn create_test_header(version: u8, header_len: i16, details_offset: i64) -> Vec<u8> {
    let mut header = vec![0u8; header_len as usize];
    LittleEndian::write_i64(&mut header[0..8], details_offset);
    LittleEndian::write_i16(&mut header[8..10], header_len);
    header[10] = version;
    header[11] = 3; // DJIFly department
    header[12] = 1; // Scrambled flag
    header
}

// ============================================================================
// 1. Bit-Exact Test Vectors from test_cryptographic_math.py (Lines 244-312)
// ============================================================================

#[test]
fn test_bit_exact_vectors_single_tenant_continuous_iv() {
    let key = hex_to_32("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
    let initial_iv = hex_to_16("202122232425262728292a2b2c2d2e2f");

    let packets: [&[u8]; 5] = [
        b"GIMBAL_PACKET_01_PITCH_YAW_ROLL_TELEMETRY",
        b"GIMBAL_PACKET_02_MOTOR_CURRENT_STATUS_NORMAL",
        b"GIMBAL_PACKET_03_STABILIZATION_HEADING_359_DEG",
        b"GIMBAL_PACKET_04_CAMERA_OPTICAL_CENTER_ALIGN",
        b"GIMBAL_PACKET_05_RETURN_TO_HOME_GIMBAL_DOWN",
    ];

    let ciphertexts_hex = [
        "ff3d006f755fa04cb18c08cb43c4ce43ffb5c197b72d93cb9e5c0139c4207359be41277eaf422bed808edfc5d413d7b1",
        "4c53b80e60147ecc85a25c2dab8f7da19601087c669be66ab2e23ed42011e14809b96610512814aab940770f5bcd477f",
        "c50c3889779627977367d1bbc6bc6d424a225a8d4066e2042783f9b3793b59b7985f173d32cde6a4154571f84ba1abfa",
        "2573201893552e6e5a068fb2bf46f9dafec20355e1e1a941918e5db033f44acaee425b8923a56bb49216deb0afef9667",
        "e6dbf4e807515252e4c8ceca0c3bae402e096d631c73465e46db9245f40e09226d697c9c4d6168474655bf1b651bb9f7",
    ];

    let expected_next_ivs = [
        hex_to_16("be41277eaf422bed808edfc5d413d7b1"),
        hex_to_16("09b96610512814aab940770f5bcd477f"),
        hex_to_16("985f173d32cde6a4154571f84ba1abfa"),
        hex_to_16("ee425b8923a56bb49216deb0afef9667"),
        hex_to_16("6d697c9c4d6168474655bf1b651bb9f7"),
    ];

    // Receiver: decrypt using AesContinuousIvEngine
    let mut engine = AesContinuousIvEngine::new(None, None);
    engine.set_key(10, key, initial_iv);
    assert_eq!(engine.get_iv(10), Some(initial_iv));

    let mut out_buf = [0u8; 128];
    for i in 0..5 {
        let ct = hex_to_bytes(ciphertexts_hex[i]);
        assert_eq!(ct.len(), 48);

        let pt_len = engine.decrypt_record(10, &ct, &mut out_buf).unwrap();
        assert_eq!(&out_buf[..pt_len], packets[i]);
        assert_eq!(engine.get_records_decrypted(10), (i + 1) as u64);
        assert_eq!(engine.get_iv(10), Some(expected_next_ivs[i]));
    }

    // Sender: verify encrypt_record_pkcs7 reproduces bit-exact ciphertexts
    let mut enc_engine = AesContinuousIvEngine::new(None, None);
    enc_engine.set_key(10, key, initial_iv);

    let mut ct_buf = [0u8; 128];
    for i in 0..5 {
        let ct_len = enc_engine.encrypt_record_pkcs7(10, packets[i], &mut ct_buf).unwrap();
        assert_eq!(ct_len, 48);
        let expected_ct = hex_to_bytes(ciphertexts_hex[i]);
        assert_eq!(&ct_buf[..ct_len], expected_ct.as_slice());
        assert_eq!(enc_engine.get_iv(10), Some(expected_next_ivs[i]));
    }
}

// ============================================================================
// 2. Continuous IV Chaining vs Naive Initial IV Reuse Failure
// ============================================================================

#[test]
fn test_continuous_iv_success_vs_naive_reuse_failure() {
    let key = hex_to_32("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
    let initial_iv = hex_to_16("202122232425262728292a2b2c2d2e2f");

    let packets: [&[u8]; 5] = [
        b"GIMBAL_PACKET_01_PITCH_YAW_ROLL_TELEMETRY",
        b"GIMBAL_PACKET_02_MOTOR_CURRENT_STATUS_NORMAL",
        b"GIMBAL_PACKET_03_STABILIZATION_HEADING_359_DEG",
        b"GIMBAL_PACKET_04_CAMERA_OPTICAL_CENTER_ALIGN",
        b"GIMBAL_PACKET_05_RETURN_TO_HOME_GIMBAL_DOWN",
    ];

    let ciphertexts_hex = [
        "ff3d006f755fa04cb18c08cb43c4ce43ffb5c197b72d93cb9e5c0139c4207359be41277eaf422bed808edfc5d413d7b1",
        "4c53b80e60147ecc85a25c2dab8f7da19601087c669be66ab2e23ed42011e14809b96610512814aab940770f5bcd477f",
        "c50c3889779627977367d1bbc6bc6d424a225a8d4066e2042783f9b3793b59b7985f173d32cde6a4154571f84ba1abfa",
        "2573201893552e6e5a068fb2bf46f9dafec20355e1e1a941918e5db033f44acaee425b8923a56bb49216deb0afef9667",
        "e6dbf4e807515252e4c8ceca0c3bae402e096d631c73465e46db9245f40e09226d697c9c4d6168474655bf1b651bb9f7",
    ];

    // Method A: Continuous IV Chaining (Passes 100%)
    let mut chained_engine = AesContinuousIvEngine::new(None, None);
    chained_engine.set_key(10, key, initial_iv);

    let mut out_buf = [0u8; 128];
    for i in 0..5 {
        let ct = hex_to_bytes(ciphertexts_hex[i]);
        let pt_len = chained_engine.decrypt_record(10, &ct, &mut out_buf).unwrap();
        assert_eq!(&out_buf[..pt_len], packets[i]);
    }

    // Method B: Naive Non-Chained IV (Reusing initial_iv on every packet)
    // Packet 0 succeeds because it naturally uses initial_iv.
    // Packets 1..4 fail to match the first 16-byte block because P_1 != D_K(C_1) ^ initial_iv.
    use cbc::cipher::{block_padding::NoPadding, BlockDecryptMut, KeyIvInit};
    let mut naive_corruptions = 0;

    for (i, ct_hex) in ciphertexts_hex.iter().enumerate() {
        let ct = hex_to_bytes(ct_hex);
        let dec = Aes256CbcDec::new((&key).into(), (&initial_iv).into());
        let mut naive_buf = [0u8; 64];
        dec.decrypt_padded_b2b_mut::<NoPadding>(&ct, &mut naive_buf[..ct.len()]).unwrap();

        if i == 0 {
            let unpadded = pkcs7_unpad(&naive_buf[..ct.len()]).unwrap();
            assert_eq!(unpadded, packets[0]);
        } else {
            // Check that first 16-byte block is corrupted
            let first_block = &naive_buf[..16];
            let expected_first_block = &packets[i][..16];
            if first_block != expected_first_block {
                naive_corruptions += 1;
            }
        }
    }

    assert_eq!(
        naive_corruptions, 4,
        "Naive IV reuse must corrupt all subsequent packets 1..4"
    );
}

// ============================================================================
// 3. Multi-Tenant FeaturePoint Isolation (Interleaved FP 10 and FP 11)
// ============================================================================

#[test]
fn test_multi_tenant_featurepoint_isolation_interleaved() {
    let fp10_key = [0x10u8; 32];
    let fp10_iv: [u8; 16] = (1u8..=16).collect::<Vec<_>>().try_into().unwrap();

    let fp11_key = [0x20u8; 32];
    let fp11_iv: [u8; 16] = (17u8..=32).collect::<Vec<_>>().try_into().unwrap();

    let stream: [(u8, &[u8]); 5] = [
        (10, b"FP10_RECORD_ONE_AILERON_PITCH_100"),
        (11, b"FP11_RECORD_ONE_STICK_STICK_STICK"),
        (10, b"FP10_RECORD_TWO_AILERON_PITCH_105"),
        (11, b"FP11_RECORD_TWO_STICK_STICK_STICK"),
        (10, b"FP10_RECORD_THREE_AILERON_PITCH_11"),
    ];

    let ciphertexts_hex = [
        "d101103e28948faa68c0e57d9daa885af10ea8c84ec4432cf31f01575d408cb00fdf5e6c5fd51fa62d742463f5ccc17d",
        "a679081fb9779066b677d4cf60ae26a11c34d97559f966100d4e7792a629695775d11ebc0ab1ec98601b55d69a08b3dc",
        "5c5044417ac18b18f43d999ca58e291be0bebc77d93d041c3fabd01f3eea9a748157bb8930b671123234d06d6dbd99c0",
        "902cac461a2abe1db9e40d4c6f188260601a49e7b37debe10f49f91e8c99706b883ab0dc544a87685ed94627bf3baefc",
        "2fb25f80ead7ac08b65ba80c41788521734291a4a762a440abc18c7daebd5d1f3b4ef309f79a7ae7c90d26d44c60e6e9",
    ];

    // Engine initialized with both keys
    let mut engine = AesContinuousIvEngine::new(None, None);
    engine.set_key(10, fp10_key, fp10_iv);
    engine.set_key(11, fp11_key, fp11_iv);

    let mut out_buf = [0u8; 128];
    for (i, &(fp, expected_pt)) in stream.iter().enumerate() {
        let ct = hex_to_bytes(ciphertexts_hex[i]);
        let pt_len = engine.decrypt_record(fp, &ct, &mut out_buf).unwrap();
        assert_eq!(&out_buf[..pt_len], expected_pt);
    }

    assert_eq!(engine.get_records_decrypted(10), 3);
    assert_eq!(engine.get_records_decrypted(11), 2);

    // Verify final IV on each domain matches expected last block
    let last_fp10_ct = hex_to_bytes(ciphertexts_hex[4]);
    let expected_fp10_final_iv: [u8; 16] = last_fp10_ct[32..48].try_into().unwrap();
    assert_eq!(engine.get_iv(10), Some(expected_fp10_final_iv));

    let last_fp11_ct = hex_to_bytes(ciphertexts_hex[3]);
    let expected_fp11_final_iv: [u8; 16] = last_fp11_ct[32..48].try_into().unwrap();
    assert_eq!(engine.get_iv(11), Some(expected_fp11_final_iv));
}

// ============================================================================
// 4. FeaturePoint 8 Plaintext Bypass (Payloads 50 and 56)
// ============================================================================

#[test]
fn test_featurepoint_8_plaintext_bypass() {
    let mut engine = AesContinuousIvEngine::empty();

    // Type 56 (KeyStorage) - 16 bytes raw token
    let ks_payload = [0x42u8; 16];
    let mut out_buf = [0u8; 64];
    let len = engine.decrypt_record(8, &ks_payload, &mut out_buf).unwrap();
    assert_eq!(len, 16);
    assert_eq!(&out_buf[..len], &ks_payload);

    // Type 50 (FlightRecordRecover) - 8 bytes crash info
    let rec_payload = [0x77u8; 8];
    let len_rec = engine.decrypt_record(8, &rec_payload, &mut out_buf).unwrap();
    assert_eq!(len_rec, 8);
    assert_eq!(&out_buf[..len_rec], &rec_payload);

    // FeaturePoint 0 (Unencrypted auxiliary)
    let aux_payload = [0x99u8; 20];
    let len_aux = engine.decrypt_record(0, &aux_payload, &mut out_buf).unwrap();
    assert_eq!(len_aux, 20);
    assert_eq!(&out_buf[..len_aux], &aux_payload);

    // Verify engine state remains untouched
    assert_eq!(engine.get_records_decrypted(8), 0);
    assert_eq!(engine.get_records_decrypted(0), 0);
    assert_eq!(engine.get_iv(8), None);
    assert_eq!(engine.get_iv(0), None);
}

// ============================================================================
// 5. PKCS7 Padding Error Handling
// ============================================================================

#[test]
fn test_pkcs7_padding_error_handling() {
    // 1. Buffer length not a multiple of 16
    let invalid_len = [0x01u8; 15];
    assert!(pkcs7_unpad(&invalid_len).is_err());

    // 2. Empty buffer
    assert!(pkcs7_unpad(&[]).is_err());

    // 3. Last byte is 0x00
    let mut b_zero = [0xAAu8; 16];
    b_zero[15] = 0x00;
    assert!(pkcs7_unpad(&b_zero).is_err());

    // 4. Last byte is > 16 (0x11 = 17)
    let mut b_overflow = [0xAAu8; 16];
    b_overflow[15] = 17;
    assert!(pkcs7_unpad(&b_overflow).is_err());

    // 5. Corrupted padding sequence: pad is 4, but bytes are [0x04, 0x04, 0x03, 0x04]
    let mut b_corrupted = [0xAAu8; 16];
    b_corrupted[12] = 0x04;
    b_corrupted[13] = 0x04;
    b_corrupted[14] = 0x03; // corrupted!
    b_corrupted[15] = 0x04;
    assert!(pkcs7_unpad(&b_corrupted).is_err());

    // 6. Valid PKCS7 unpadding
    let mut b_valid = [0x55u8; 32];
    b_valid[31] = 0x01;
    let unpadded = pkcs7_unpad(&b_valid).unwrap();
    assert_eq!(unpadded.len(), 31);
    assert_eq!(unpadded, &[0x55u8; 31]);
}

// ============================================================================
// 6. MissingKey Error Handling
// ============================================================================

#[test]
fn test_missing_key_error_handling() {
    let mut engine = AesContinuousIvEngine::empty();

    let ciphertext = [0x55u8; 32];
    let mut out_buf = [0u8; 64];

    // FeaturePoint 1 is unkeyed
    assert_eq!(
        engine.decrypt_record(1, &ciphertext, &mut out_buf).unwrap_err(),
        FlightReaderError::MissingKey { feature_point: 1 }
    );

    // FeaturePoint 10 is unkeyed
    assert_eq!(
        engine.decrypt_record(10, &ciphertext, &mut out_buf).unwrap_err(),
        FlightReaderError::MissingKey { feature_point: 10 }
    );

    // Out-of-bounds FeaturePoint (e.g. 16)
    assert_eq!(
        engine.decrypt_record(16, &ciphertext, &mut out_buf).unwrap_err(),
        FlightReaderError::MissingKey { feature_point: 16 }
    );
}

// ============================================================================
// 7. End-to-End Synthetic v13 and v14 Log Demuxing via RecordEnvelopeIterator
// ============================================================================

#[test]
fn test_synthetic_v13_v14_e2e_demuxing_with_aes() {
    for version in [13u8, 14u8] {
        let mut file_buf = create_test_header(version, 100, 120);
        file_buf.extend_from_slice(&[0x11; 20]); // details block

        let base_key = [0x01u8; 32];
        let base_iv = [0x02u8; 16];

        let gimbal_key = [0x03u8; 32];
        let gimbal_iv = [0x04u8; 16];

        let mut enc_engine = AesContinuousIvEngine::empty();
        enc_engine.set_key(1, base_key, base_iv);
        let gimbal_fp = if version == 13 { 1 } else { 10 };
        enc_engine.set_key(gimbal_fp, gimbal_key, gimbal_iv);

        // Record 1: KeyStorage (Type 56, FP 8 Plaintext Bypass)
        let ks_pt = [0xAAu8; 16];
        file_buf.push(56);
        file_buf.extend_from_slice(&(ks_pt.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&ks_pt);
        file_buf.push(RECORD_DELIMITER);

        // Record 2: OSD Telemetry (Type 1, FP 1 Base) - Encrypted
        let osd_pt = b"SYNTHETIC_OSD_RECORD_TELEMETRY_DATA_1";
        let mut osd_ct = [0u8; 64];
        let osd_ct_len = enc_engine.encrypt_record_pkcs7(1, osd_pt, &mut osd_ct).unwrap();
        file_buf.push(1);
        file_buf.extend_from_slice(&(osd_ct_len as u16).to_le_bytes());
        file_buf.extend_from_slice(&osd_ct[..osd_ct_len]);
        file_buf.push(RECORD_DELIMITER);

        // Record 3: FlightRecordRecover (Type 50, FP 8 Plaintext Bypass)
        let rec_pt = [0xBBu8; 8];
        file_buf.push(50);
        file_buf.extend_from_slice(&(rec_pt.len() as u16).to_le_bytes());
        file_buf.extend_from_slice(&rec_pt);
        file_buf.push(RECORD_DELIMITER);

        // Record 4: Gimbal Telemetry (Type 3) - FP 1 in v13, FP 10 in v14
        let gimbal_pt = b"SYNTHETIC_GIMBAL_PITCH_YAW_STABILIZATION_1";
        let mut gimbal_ct = [0u8; 64];
        let gimbal_ct_len = enc_engine
            .encrypt_record_pkcs7(gimbal_fp, gimbal_pt, &mut gimbal_ct)
            .unwrap();
        file_buf.push(3);
        file_buf.extend_from_slice(&(gimbal_ct_len as u16).to_le_bytes());
        file_buf.extend_from_slice(&gimbal_ct[..gimbal_ct_len]);
        file_buf.push(RECORD_DELIMITER);

        // Parse with RecordEnvelopeIterator
        let header = TxtHeader::parse(&file_buf).unwrap();
        let mut iter = RecordEnvelopeIterator::new(&file_buf, &header)
            .unwrap()
            .with_key(1, base_key, base_iv)
            .with_key(gimbal_fp, gimbal_key, gimbal_iv);

        let mut scratch = [0u8; 512];

        // Rec 1: KeyStorage (bypass)
        let env1 = iter.next().unwrap().unwrap();
        assert_eq!(env1.record_type, 56);
        assert_eq!(get_feature_point(version, 56), 8);
        let pt1 = iter.decode_into(&env1, &mut scratch).unwrap();
        assert_eq!(pt1, &ks_pt);

        // Rec 2: OSD (encrypted)
        let env2 = iter.next().unwrap().unwrap();
        assert_eq!(env2.record_type, 1);
        assert_eq!(get_feature_point(version, 1), 1);
        let pt2 = iter.decode_into(&env2, &mut scratch).unwrap();
        assert_eq!(pt2, osd_pt);

        // Rec 3: FlightRecordRecover (bypass)
        let env3 = iter.next().unwrap().unwrap();
        assert_eq!(env3.record_type, 50);
        assert_eq!(get_feature_point(version, 50), 8);
        let pt3 = iter.decode_into(&env3, &mut scratch).unwrap();
        assert_eq!(pt3, &rec_pt);

        // Rec 4: Gimbal (encrypted)
        let env4 = iter.next().unwrap().unwrap();
        assert_eq!(env4.record_type, 3);
        assert_eq!(get_feature_point(version, 3), gimbal_fp);
        let pt4 = iter.decode_into(&env4, &mut scratch).unwrap();
        assert_eq!(pt4, gimbal_pt);

        assert!(iter.next().is_none());
    }
}

// ============================================================================
// 8. Zero Heap Allocation Verification
// ============================================================================

#[test]
fn test_zero_heap_allocation_decryption_hot_path() {
    let key = [0x77u8; 32];
    let iv = [0x88u8; 16];

    let mut enc = AesContinuousIvEngine::new(Some(key), Some(iv));
    let mut dec = AesContinuousIvEngine::new(Some(key), Some(iv));

    let sample_payload = b"OSD_TELEMETRY_VELOCITY_NED_COORDINATES_HEADING";
    let mut ct_buf = [0u8; 64];
    let ct_len = enc.encrypt_record_pkcs7(1, sample_payload, &mut ct_buf).unwrap();

    let mut stack_scratch = [0u8; 256];

    // Execute 10,000 iterations without creating heap buffers
    for _ in 0..10_000 {
        let mut ct_clone = ct_buf; // stack copy
        let pt_len = dec
            .decrypt_slice_in_place(1, &mut ct_clone[..ct_len])
            .unwrap();
        assert_eq!(&ct_clone[..pt_len], sample_payload);

        // Reset IV for next iteration
        dec.set_key(1, key, iv);
    }

    // Also verify RawRecordEnvelope::decode_into_with_aes on fixed buffer
    let env = RawRecordEnvelope::new(1, &ct_buf[..ct_len]);
    let pt = env
        .decode_into_with_aes(14, &mut stack_scratch, Some(&mut dec))
        .unwrap();
    assert_eq!(pt, sample_payload);
}
